using System;using System.Runtime.InteropServices;using System.Windows.Automation;using System.IO;
public static class OwnedTrialInput {
 [StructLayout(LayoutKind.Sequential)]public struct POINT{public int x,y;}
 [StructLayout(LayoutKind.Sequential)]public struct MOUSEINPUT{public int dx,dy;public uint data,flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Sequential)]public struct KEYBDINPUT{public ushort vk,scan;public uint flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Explicit,Size=32)]public struct UNION{[FieldOffset(0)]public MOUSEINPUT mouse;[FieldOffset(0)]public KEYBDINPUT key;}
 [StructLayout(LayoutKind.Sequential)]public struct INPUT{public uint type;public UNION data;}
 [DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint count,INPUT[] inputs,int size);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")]static extern bool GetPhysicalCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern int GetSystemMetrics(int index);
 [DllImport("user32.dll")]static extern IntPtr WindowFromPoint(POINT p);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr w,out uint pid);
 static int hwnd;static string log;
 static void Emit(INPUT i){uint n=SendInput(1,new[]{i},Marshal.SizeOf<INPUT>());File.AppendAllText(log,"type="+i.type+" flags="+(i.type==1?i.data.key.flags:i.data.mouse.flags)+" count="+n+" error="+Marshal.GetLastWin32Error()+"\n");if(n!=1)throw new InvalidOperationException("SendInput failed");}
 static void Key(ushort vk,bool down,ushort scan=0){Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=vk,scan=scan,flags=(down?0u:2u)|(scan==0?0u:4u)}}});}
 static void Foreground(){if(GetForegroundWindow().ToInt64()!=hwnd)throw new InvalidOperationException("Owned Trial foreground lost");}
 public static AutomationElement Window(string app,bool source){AutomationElement found=null;foreach(AutomationElement w in AutomationElement.RootElement.FindAll(TreeScope.Children,Condition.TrueCondition)){if(source?!w.Current.Name.StartsWith("TrialPage Input · original runtime",StringComparison.Ordinal):w.Current.Name!="Replica TrialPage verification")continue;var path=System.Diagnostics.Process.GetProcessById(w.Current.ProcessId).MainModule.FileName;if(source?!path.EndsWith(@"\Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):!path.Equals(Path.Combine(app,"ReplicaProbe.exe"),StringComparison.OrdinalIgnoreCase))continue;if(found!=null)throw new InvalidOperationException("Exact own Trial uniqueness");found=w;}if(found==null)throw new InvalidOperationException("Own Trial missing");if(source){bool url=false;foreach(AutomationElement e in found.FindAll(TreeScope.Descendants,Condition.TrueCondition)){object pat;if(e.TryGetCurrentPattern(ValuePattern.Pattern,out pat)&&(((ValuePattern)pat).Current.Value=="http://10.211.55.2:8768/trialpage-input.html"||((ValuePattern)pat).Current.Value=="10.211.55.2:8768/trialpage-input.html"||((ValuePattern)pat).Current.Value=="http://10.211.55.2:8768/trialpage-input.html?reduced=1"||((ValuePattern)pat).Current.Value=="10.211.55.2:8768/trialpage-input.html?reduced=1"))url=true;}if(!url)throw new InvalidOperationException("Exact source URL required");}return found;}
 public static void Run(string app,bool source,string id,string mode){var old=SetThreadDpiAwarenessContext(new IntPtr(-4));bool heldCtrl=false,heldKey=false,heldButton=false;ushort key=0,heldScan=0;log=Path.Combine(app,"trialpage-input-transport.txt");try{
 if(id!="trial-host"&&id!="trial-db"&&id!="trial-validInput"&&id!="trial-invalidInput"&&id!="flag-trial.consent")throw new InvalidOperationException("Fixed Trial target required");if(mode!="edit"&&mode!="pointer"&&mode!="space"&&mode!="enter")throw new InvalidOperationException("Fixed Trial mode required");
 var w=Window(app,source);hwnd=w.Current.NativeWindowHandle;int pid=w.Current.ProcessId;var bounds=w.Current.BoundingRectangle;AutomationElement b=null;
 foreach(AutomationElement x in w.FindAll(TreeScope.Descendants,Condition.TrueCondition)){bool match=x.Current.AutomationId==id;if(source&&id=="flag-trial.consent")match=x.Current.ControlType==ControlType.CheckBox&&(x.Current.Name=="예시 시험안과 기대 결과를 확인했습니다."||x.Current.Name=="I have reviewed the sample trial plan and expected results.");if(match){if(b!=null)throw new InvalidOperationException("Unique Trial target");b=x;}}
 if(b==null)throw new InvalidOperationException("Trial target missing");string expectedName=b.Current.Name;var rect=b.Current.BoundingRectangle;SetForegroundWindow(new IntPtr(hwnd));System.Threading.Thread.Sleep(150);Foreground();
 if(mode=="pointer"){if(rect.Width<19||rect.Width>61||Math.Abs(rect.Width-rect.Height)>1||!bounds.Contains(rect))throw new InvalidOperationException("Visible checkbox frame required");double px=rect.Left+rect.Width/2,py=rect.Top+rect.Height/2;int left=GetSystemMetrics(76),top=GetSystemMetrics(77),width=GetSystemMetrics(78),height=GetSystemMetrics(79);if(px<left||py<top||px>=left+width||py>=top+height)throw new InvalidOperationException("Pointer outside screen");Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{dx=(int)Math.Round((px-left)*65535/(width-1)),dy=(int)Math.Round((py-top)*65535/(height-1)),flags=0x8000|0x4000|1}}});System.Threading.Thread.Sleep(80);Foreground();POINT actual;GetPhysicalCursorPos(out actual);uint hit;GetWindowThreadProcessId(WindowFromPoint(actual),out hit);File.AppendAllText(log,"point="+actual.x+","+actual.y+" intended="+px+","+py+" hitPid="+hit+"\n");if(Math.Abs(actual.x-px)>1||Math.Abs(actual.y-py)>1||hit!=pid)throw new InvalidOperationException("Fresh physical hit guard");Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{flags=2}}});heldButton=true;System.Threading.Thread.Sleep(40);Foreground();Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{flags=4}}});heldButton=false;}
 else{b.SetFocus();System.Threading.Thread.Sleep(150);var f=AutomationElement.FocusedElement;rect=b.Current.BoundingRectangle;if(!bounds.Contains(rect))throw new InvalidOperationException("Visible focused field required");if(f.Current.ProcessId!=pid||(source&&id=="flag-trial.consent"?f.Current.Name!=expectedName:f.Current.AutomationId!=id))throw new InvalidOperationException("Exact fresh Trial focus required");Foreground();
 if(mode=="edit"){if(id=="flag-trial.consent")throw new InvalidOperationException("Editable target required");Key(17,true);heldCtrl=true;Key(65,true);heldKey=true;key=65;Key(65,false);heldKey=false;Key(17,false);heldCtrl=false;foreach(char c in "owned-example"){Foreground();Key(0,true,c);heldKey=true;key=0;heldScan=c;Key(0,false,c);heldKey=false;heldScan=0;System.Threading.Thread.Sleep(10);}}
 else{key=mode=="space"?(ushort)32:(ushort)13;Key(key,true);heldKey=true;System.Threading.Thread.Sleep(40);Foreground();Key(key,false);heldKey=false;}}
 System.Threading.Thread.Sleep(180);Foreground();
 }finally{if(heldKey)Key(key,false,heldScan);if(heldCtrl)Key(17,false);if(heldButton)Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{flags=4}}});if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);log=null;}}
 public static void Hover(string app,bool source,string mode){var old=SetThreadDpiAwarenessContext(new IntPtr(-4));log=Path.Combine(app,"trialpage-hover-transport.txt");try{if(mode!="hover"&&mode!="leave"&&mode!="cancel")throw new InvalidOperationException("Fixed hover mode");var w=Window(app,source);hwnd=w.Current.NativeWindowHandle;int pid=w.Current.ProcessId;var frame=w.Current.BoundingRectangle;AutomationElement row=null;foreach(AutomationElement e in w.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.DataItem))){bool match=false;if(e.Current.ClassName!="Row"&&e.Current.LocalizedControlType!="행")continue;foreach(AutomationElement t in e.FindAll(TreeScope.Descendants,Condition.TrueCondition)){if(t.Current.Name=="앱 생성 자료 입력·조회"||t.Current.Name=="Insert and read app-owned test data")match=true;}if(match){if(row!=null)throw new InvalidOperationException("Unique first Trial row");row=e;}}if(row==null)throw new InvalidOperationException("First Trial row missing");var r=row.Current.BoundingRectangle;var leave=w.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,"TrialPage-scroll"));if(leave==null)throw new InvalidOperationException("Exact leave utility");if(!frame.Contains(new System.Windows.Point(r.Left+r.Width/2,r.Top+r.Height/2))){((InvokePattern)leave.GetCurrentPattern(InvokePattern.Pattern)).Invoke();System.Threading.Thread.Sleep(200);r=row.Current.BoundingRectangle;}if(r.Width<300||r.Height<20||r.Height>300)throw new InvalidOperationException("First Trial row geometry");var lr=leave.Current.BoundingRectangle;SetForegroundWindow(new IntPtr(hwnd));System.Threading.Thread.Sleep(150);Foreground();if(mode=="leave")Move(r,lr,frame,pid,true);else{Move(r,lr,frame,pid,false);if(mode=="cancel"){System.Threading.Thread.Sleep(60);Move(r,lr,frame,pid,true);}}System.Threading.Thread.Sleep(200);Foreground();}finally{if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);log=null;}}
 static void Move(System.Windows.Rect row,System.Windows.Rect leave,System.Windows.Rect frame,int pid,bool outside){var r=outside?leave:row;double px=r.Left+r.Width/2,py=r.Top+r.Height/2;var point=new System.Windows.Point(px,py);if(!frame.Contains(point))throw new InvalidOperationException("Visible owned row point");int left=GetSystemMetrics(76),top=GetSystemMetrics(77),width=GetSystemMetrics(78),height=GetSystemMetrics(79);Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{dx=(int)Math.Round((px-left)*65535/(width-1)),dy=(int)Math.Round((py-top)*65535/(height-1)),flags=0x8000|0x4000|1}}});System.Threading.Thread.Sleep(30);Foreground();POINT actual;GetPhysicalCursorPos(out actual);uint hit;GetWindowThreadProcessId(WindowFromPoint(actual),out hit);File.AppendAllText(log,"physical="+actual.x+","+actual.y+" intended="+px+","+py+" hitPid="+hit+"\n");if(Math.Abs(actual.x-px)>1||Math.Abs(actual.y-py)>1||hit!=pid)throw new InvalidOperationException("Fresh row hover physicalpoint");}

}
public static class TrialPaint {
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr c);
 public static void Capture(string app,bool source,string label){var old=SetThreadDpiAwarenessContext(new IntPtr(-4));try{var w=OwnedTrialInput.Window(app,source);var h=w.Current.NativeWindowHandle;var rect=w.Current.BoundingRectangle;SetForegroundWindow(new IntPtr(h));System.Threading.Thread.Sleep(150);if(GetForegroundWindow().ToInt64()!=h||rect.Width<600||rect.Height<600||rect.Width>7000||rect.Height>5000)throw new InvalidOperationException("Own visible Trial paint guard");using(var b=new System.Drawing.Bitmap((int)rect.Width,(int)rect.Height)){using(var g=System.Drawing.Graphics.FromImage(b))g.CopyFromScreen((int)rect.X,(int)rect.Y,0,0,b.Size);b.Save(Path.Combine(app,label+".png"),System.Drawing.Imaging.ImageFormat.Png);}}finally{if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);}}
}
